  door(("David: “I'm so sorry, Phoebe. I ____ to go to Minsk tonight.” → (1 слово)", "David: “I'm so sorry, Phoebe. I ____ to go to Minsk tonight.” → (1 słowo)", "David: “I'm so sorry, Phoebe. I ____ to go to Minsk tonight.” → (1 word)"),
       ["have"], ("I have to + дієслово.", "I have to + czasownik.", "I have to + verb.")),
